import numpy as np, torch, model
net=model.load(); d=torch.tensor(np.load('contrast_c1_out_act_k8.npy')).float()
N=8192; rs=np.random.RandomState(2)
xi=rs.randn(N,2).astype(np.float32); c=rs.rand(N).astype(np.float32)
st={}
ov=net.velocity
def vel(x,t,c,capture=(),count=False):
    st['x']=x; st['t']=t; return ov(x,t,c,capture,count=count)
net.velocity=vel
cfg={'on':False}
def hk(m,inp,out):
    if not cfg['on']: return out
    k=int(round((1-float(st['t'][0]))*20))
    if not (cfg['lo']<=k<cfg['hi']): return out
    f=(inp[0]@d + cfg['b'])>0
    return out+ f[:,None].float()*torch.tensor(cfg['c0'])
net.out.register_forward_hook(hk)
a0=model.decode(net,xi,c).numpy()
def lab(a):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); r=np.linalg.norm(a,axis=1)
    return ang, r, (ang>15)&(ang<65)&(r>1.8)
ang0,r0,T0=lab(a0)
print('target0',T0.mean())
def ev(**kw):
    cfg.update(on=True,**kw); a=model.decode(net,xi,c).numpy(); cfg['on']=False
    ang,r,T=lab(a)
    mv=np.linalg.norm(a-a0,axis=1)>0.47
    h0,_=np.histogram(ang0[~T0],36,(-180,180)); h1,_=np.histogram(ang[~T],36,(-180,180))
    tv=0.5*np.abs(h0/h0.sum()-h1/h1.sum()).sum()
    btw=((ang>65)&(ang<165)).mean()-((ang0>65)&(ang0<165)).mean()
    return T.mean(), mv[~T0].mean(), tv, btw
for b in [-49.08,-40,-60]:
  for hi in [9,12]:
    for m in [3,5]:
      for th in [60,90,120,135]:
        v=np.array([np.cos(np.radians(th)),np.sin(np.radians(th))],np.float32)*m
        print(b,hi,m,th,np.round(ev(lo=0,hi=hi,b=b,c0=v),3))

